def transform(grid):
    from collections import deque
    g=[r[:] for r in grid]; h=len(g); w=len(g[0])
    seen=set(); out=[[7]*w for _ in range(h)]
    for r in range(h):
      for c in range(w):
        if g[r][c]==1 or (r,c) in seen: continue
        color=g[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          x,y=q.pop(); comp.append((x,y))
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=x+dx,y+dy
            if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]==color:
              seen.add((a,b)); q.append((a,b))
        cells=set(comp); special=[]; marked=False
        frontier=[]
        for x,y in comp:
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=x+dx,y+dy
            if 0<=a<h and 0<=b<w and g[a][b]==1:
              marked=True; frontier.append((a,b))
        # A non-blue plus centre has four blue orthogonal neighbours.
        for x,y in comp:
          if all(0<=x+dx<h and 0<=y+dy<w and g[x+dx][y+dy]==1 for dx,dy in ((1,0),(-1,0),(0,1),(0,-1))):
            special.append(color)
        new=special[0] if special else (color if marked else 7)
        for x,y in comp: out[x][y]=new
        # Grow through the blue marker pixels into this region.
        q=deque(frontier)
        while q:
          x,y=q.popleft()
          if out[x][y]==new: continue
          out[x][y]=new
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=x+dx,y+dy
            if 0<=a<h and 0<=b<w and g[a][b]==1: q.append((a,b))
    return out

